import React, { useState, useEffect } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import {
  Box,
  Button,
  Grid,
  TextField,
  Typography,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Chip,
} from "@mui/material";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { Scanner } from "@yudiel/react-qr-scanner";
import jsQR from "jsqr";
import toastMessage from "../../utils/toastMessage";
import { verifyUpiVpa, B2BBankTransfer, Getprofile } from "../../api/login/Login";

const UpiTransferPage = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const activeWallet = location?.state?.walletType || "MAIN";
  const [profile, setProfile] = useState(null);

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const res = await Getprofile();
        if (res?.data?.data) {
          setProfile(res.data.data);
        }
      } catch (err) {
        console.error("Failed to load user profile in UPI transfer:", err);
      }
    };
    fetchProfile();
  }, []);

  const isCashback = activeWallet === "CASHBACK";
  const upiMin = profile?.cashback_upi_min_per_txn !== undefined && profile?.cashback_upi_min_per_txn !== null ? Number(profile.cashback_upi_min_per_txn) : 500;
  const upiMax = profile?.cashback_upi_max_per_txn !== undefined && profile?.cashback_upi_max_per_txn !== null ? Number(profile.cashback_upi_max_per_txn) : 25000;
  const upiDaily = profile?.cashback_upi_daily_limit !== undefined && profile?.cashback_upi_daily_limit !== null ? Number(profile.cashback_upi_daily_limit) : 100000;

  const handleBack = () => {
    if (location?.state?.fromCashbackSettlement) {
      navigate("/Dashboard", {
        state: { openCashbackSettlement: true, initialView: "BANK_OPTIONS" },
      });
    } else {
      navigate(-1);
    }
  };
  const [verified, setVerified] = useState(false);
  const [skipVerify, setSkipVerify] = useState(false);
  const [qrHasAmount, setQrHasAmount] = useState(false);
  const [loading, setLoading] = useState(false);
  const [openQr, setOpenQr] = useState(false);
  const [openTpin, setOpenTpin] = useState(false);
  const [tpin, setTpin] = useState("");

  const [form, setForm] = useState({
    transfer_mode: "UPI",
    vpa: "",
    transfer_amount: "",
    beneficiary_name: "",
    beneficiary_account_name: "",
    beneficiary_email: "",
    beneficiary_mobile: "",
    beneficiary_add: "",
    beneficiary_city: "",
    beneficiary_state: "",
    beneficiary_pin_code: "",
  });

  const setField = (k, v) =>
    setForm((p) => ({ ...p, [k]: v }));

  const verifyUpi = async (vpa) => {
    try {
      setLoading(true);
      const res = await verifyUpiVpa({
        accountNumber: vpa,
        transfer_mode: "UPI",
      });

      if (res?.data?.success) {
        setVerified(true);
        const name = res.data.data?.name || "";
        const bankName = res.data.data?.bank_name || name || "UPI Account";
        setField("beneficiary_name", name);
        setField("beneficiary_account_name", bankName);
        toastMessage(false, res?.data?.message || "UPI Verified");
      } else {
        toastMessage(true, res?.data?.message);
      }
    } catch (error) {
      toastMessage(true, error?.response?.data?.message || "Verification error");
    } finally {
      setLoading(false);
    }
  };
  // Added by Aman singh for without verfiy
  const handleWithoutVerify = () => {
    if (!form.vpa) {
      toastMessage(true, "Enter UPI ID first");
      return;
    }
    setSkipVerify(true);
    setVerified(true);
  };

  const handleQrData = (raw) => {
    if (!raw?.toLowerCase().startsWith("upi://")) {
      toastMessage(true, "Invalid UPI QR");
      return;
    }

    const params = new URLSearchParams(raw.split("?")[1] || "");
    const vpa = params.get("pa");
    const amount = params.get("am");

    if (vpa) {
      const decodedVpa = decodeURIComponent(vpa);
      setField("vpa", decodedVpa);
      setVerified(false);
      verifyUpi(decodedVpa);
    }

    if (amount && !isNaN(amount)) {
      setField("transfer_amount", amount);
      setQrHasAmount(true);
    } else {
      setQrHasAmount(false);
    }

    setOpenQr(false);
  };


  const submitPayout = async () => {
    if (!verified) {
      toastMessage(true, "UPI verification required");
      return;
    }

    if (!/^\d{4}$/.test(tpin)) {
      toastMessage(true, "Invalid TPIN");
      return;
    }

    const amt = Number(form.transfer_amount);
    if (!amt || amt <= 0) {
      toastMessage(true, "Enter valid transfer amount");
      return;
    }

    if (isCashback) {
      if (upiMin > 0 && amt < upiMin) {
        toastMessage(true, `Minimum payout amount is ₹${upiMin.toLocaleString("en-IN")}`);
        return;
      }
      if (upiMax > 0 && amt > upiMax) {
        toastMessage(true, `Maximum payout limit per transaction is ₹${upiMax.toLocaleString("en-IN")}`);
        return;
      }
    }

    try {
      setLoading(true);

      const name = form.beneficiary_name || "UPI User";
      const accountName = form.beneficiary_account_name || name;

      const payload = {
        transfer_mode: "UPI",
        vpa: form.vpa,
        transfer_amount: Number(form.transfer_amount),
        beneficiary_name: name,
        beneficiary_account_name: accountName,
        beneficiary_account_type: form.beneficiary_account_type || "SAVINGS",
        beneficiary_email: form.beneficiary_email,
        beneficiary_mobile: form.beneficiary_mobile,
        beneficiary_add: form.beneficiary_add,
        beneficiary_city: form.beneficiary_city,
        beneficiary_state: form.beneficiary_state,
        beneficiary_pin_code: form.beneficiary_pin_code,
        tpin,
        wallet_type: activeWallet,
      };

      // Remove optional empty string fields so backend Joi validation does not throw "not allowed to be empty"
      Object.keys(payload).forEach((key) => {
        if (payload[key] === "" && key !== "beneficiary_account_name" && key !== "beneficiary_account_type") {
          delete payload[key];
        }
      });

      const res = await B2BBankTransfer(payload);

      if (res?.data?.success) {
        toastMessage(false, res?.data?.message || "UPI Payout Successful");
        reset();
      } else {
        toastMessage(true, res?.data?.message);
      }
    }
    catch (error) {
      toastMessage(true, error?.response?.data?.message || "Server error");
    } finally {
      setLoading(false);
    }
  };

  const reset = () => {
    setVerified(false);
    setSkipVerify(false);
    setQrHasAmount(false);
    setOpenTpin(false);
    setTpin("");
    setForm({
      transfer_mode: "UPI",
      vpa: "",
      transfer_amount: "",
      beneficiary_name: "",
      beneficiary_account_name: "",
      beneficiary_email: "",
      beneficiary_mobile: "",
      beneficiary_add: "",
      beneficiary_city: "",
      beneficiary_state: "",
      beneficiary_pin_code: "",
    });
  };

  return (
    <>
      {/* Top Header Bar - Outside form card */}
      <Box
        sx={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          flexWrap: "wrap",
          gap: 1.5,
          mb: 2,
        }}
      >
        <Button
          variant="contained"
          size="small"
          startIcon={<ArrowBackIcon />}
          onClick={handleBack}
          sx={{
            textTransform: "none",
            fontWeight: 700,
            borderRadius: "8px",
            bgcolor: "#cc9840",
            color: "#ffffff",
            boxShadow: "0 2px 6px rgba(204, 152, 64, 0.35)",
            "&:hover": {
              bgcolor: "#b5822e",
              boxShadow: "0 4px 10px rgba(204, 152, 64, 0.45)",
            },
          }}
        >
          Back
        </Button>
        {isCashback && (
          <Box sx={{ display: "flex", gap: 1, alignItems: "center", flexWrap: "wrap" }}>
            <Chip
              label="Cashback Wallet Payout"
              size="small"
              sx={{
                bgcolor: "#ede9fe",
                color: "#6d28d9",
                fontWeight: 700,
                fontSize: "12px",
                px: 0.5,
              }}
            />
            <Chip
              label={`Per Txn: ₹${upiMin.toLocaleString("en-IN")} - ₹${upiMax.toLocaleString("en-IN")} | Daily Limit: ₹${upiDaily.toLocaleString("en-IN")}`}
              size="small"
              variant="outlined"
              sx={{
                borderColor: "#c4b5fd",
                color: "#5b21b6",
                fontWeight: 600,
                fontSize: "11.5px",
                bgcolor: "#f5f3ff",
              }}
            />
          </Box>
        )}
      </Box>

      {/* Main Form Container */}
      <Box p={3} bgcolor="#fff" borderRadius={2} sx={{ boxShadow: "0 2px 10px rgba(0,0,0,0.04)" }}>
        <Typography variant="h6" fontWeight={700} mb={2.5}>
          Send to Own UPI
        </Typography>

        <Grid container spacing={2}>
          <Grid item xs={12} md={4}>
            <TextField
              fullWidth
              className="mui-autofill-fix"
              label="UPI ID"
              placeholder="e.g. 9876543210@ybl"
              value={form.vpa}
              disabled={verified || loading}
              onChange={(e) => {
                setField("vpa", e.target.value.toLowerCase());
                setVerified(false);
              }}
              sx={{
                "& .MuiInputLabel-root.Mui-focused": {
                  color: "#cc9840",
                },
                "& input::placeholder": {
                  color: "#94a3b8",
                  fontSize: "13.5px",
                  opacity: 0.85,
                },
              }}
            />

            {/* Added by Aman singh  */}
            {!verified && (
              <Box mt={1} display="flex" gap={1}>
                <Button
                  onClick={() => setOpenQr(true)}
                  disabled={loading}
                >
                  Scan QR
                </Button>
                <Button
                  onClick={() => verifyUpi(form.vpa)}
                  disabled={!form.vpa || loading}
                >
                  {loading ? "Verifying..." : "Verify"}
                </Button>
                <Button
                  color="warning"
                  onClick={handleWithoutVerify}
                  disabled={!form.vpa || loading}
                >
                  Without Verify
                </Button>
              </Box>
            )}
          </Grid>

          {/* Right side: Multi-bank UPI handle examples */}
          {!verified && (
            <Grid item xs={12} md={8}>
              <Box
                sx={{
                  p: 1.8,
                  borderRadius: "12px",
                  bgcolor: "#f8fafc",
                  border: "1px dashed #cbd5e1",
                  display: "flex",
                  flexDirection: "column",
                  gap: 1,
                }}
              >
                <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 0.5 }}>
                  <Typography sx={{ fontSize: "12.5px", fontWeight: 700, color: "#334155" }}>
                    💡 Popular Bank UPI Handles (Examples):
                  </Typography>
                  <Typography sx={{ fontSize: "11px", color: "#64748b" }}>
                    Tap any handle to add to your input
                  </Typography>
                </Box>

                <Box sx={{ display: "flex", flexWrap: "wrap", gap: 0.8 }}>
                  {[
                    { handle: "@ybl", bank: "PhonePe / YES Bank" },
                    { handle: "@ibl", bank: "PhonePe / ICICI" },
                    { handle: "@paytm", bank: "Paytm" },
                    { handle: "@oksbi", bank: "GPay / SBI" },
                    { handle: "@okhdfcbank", bank: "GPay / HDFC" },
                    { handle: "@okaxis", bank: "GPay / Axis" },
                    { handle: "@okicici", bank: "GPay / ICICI" },
                    { handle: "@upi", bank: "BHIM UPI" },
                  ].map((item) => (
                    <Chip
                      key={item.handle}
                      label={
                        <span>
                          <strong style={{ color: "#0f172a" }}>{item.handle}</strong>
                          <span style={{ color: "#64748b", fontSize: "11px", marginLeft: "4px" }}>
                            ({item.bank})
                          </span>
                        </span>
                      }
                      size="small"
                      clickable
                      onClick={() => {
                        const current = (form.vpa || "").trim();
                        if (current.includes("@")) {
                          const base = current.split("@")[0];
                          setField("vpa", (base + item.handle).toLowerCase());
                        } else if (current) {
                          setField("vpa", (current + item.handle).toLowerCase());
                        } else {
                          setField("vpa", ("9876543210" + item.handle).toLowerCase());
                        }
                        setVerified(false);
                      }}
                      sx={{
                        borderRadius: "8px",
                        bgcolor: "#ffffff",
                        border: "1px solid #e2e8f0",
                        fontSize: "12px",
                        py: 1.6,
                        boxShadow: "0 1px 2px rgba(0,0,0,0.03)",
                        "&:hover": {
                          bgcolor: "#f1f5f9",
                          borderColor: "#cc9840",
                        },
                      }}
                    />
                  ))}
                </Box>

                <Typography sx={{ fontSize: "11.5px", color: "#64748b" }}>
                  Format: <b>Mobile Number</b> or <b>Username</b> + bank handle (e.g. <code>9876543210@ybl</code>, <code>rahul@oksbi</code>)
                </Typography>
              </Box>
            </Grid>
          )}

          {verified && (
            <>
              {/* ✅ Beneficiary Name + Verified */}
              {/* <Grid item xs={12} md={4}>
                <TextField
                  fullWidth
                  label="Beneficiary Name"
                  className="mui-autofill-fix"
                  value={form.beneficiary_name}
                  disabled
                />
                <Typography
                  variant="caption"
                  sx={{ color: "green", fontWeight: 600 }}
                >
                  ✔ Verified
                </Typography>
              </Grid> */}
              {/* Added by Aman singh */}
              <Grid item xs={12} md={4}>
                <TextField
                  fullWidth
                  label="Beneficiary Name"
                  className="mui-autofill-fix"
                  value={form.beneficiary_name}
                  disabled={!skipVerify || loading}
                  onChange={(e) => setField("beneficiary_name", e.target.value)}
                />
                <Typography
                  variant="caption"
                  sx={{ color: skipVerify ? "orange" : "green", fontWeight: 600 }}
                >
                  {skipVerify ? "⚠ Not Verified" : "✔ Verified"}
                </Typography>
              </Grid>

              {/* ✅ Bank Name */}
              <Grid item xs={12} md={4}>
                <TextField
                  fullWidth
                  label="Bank Name"
                  className="mui-autofill-fix"
                  value={form.beneficiary_account_name}
                  onChange={(e) =>
                    setField("beneficiary_account_name", e.target.value)
                  }
                />
              </Grid>

              {/* ✅ Amount */}
              <Grid item xs={12} md={4}>
                <TextField
                  fullWidth
                  label="Amount"
                  className="mui-autofill-fix"
                  value={form.transfer_amount}
                  disabled={loading || qrHasAmount}
                  onChange={(e) =>
                    setField("transfer_amount", e.target.value)
                  }
                  helperText={
                    isCashback ? (
                      <span style={{ color: "#6d28d9", fontWeight: 600 }}>
                        ⚡ Limit: ₹{upiMin.toLocaleString("en-IN")} - ₹{upiMax.toLocaleString("en-IN")} / txn (Daily: ₹{upiDaily.toLocaleString("en-IN")})
                      </span>
                    ) : undefined
                  }
                />
              </Grid>

              {/* ✅ Other editable fields */}
              {/* {[
                ["beneficiary_email", "Email"],
                ["beneficiary_mobile", "Mobile"],
                ["beneficiary_add", "Address"],
                ["beneficiary_city", "City"],
                ["beneficiary_state", "State"],
                ["beneficiary_pin_code", "PIN Code"],
              ].map(([key, label]) => (
                <Grid item xs={12} md={4} key={key}>
                  <TextField
                    fullWidth
                    className="mui-autofill-fix"
                    label={label}
                    value={form[key]}
                    disabled={loading}
                    onChange={(e) => setField(key, e.target.value)}
                  />
                </Grid>
              ))} */}
              {/* ✅ Other editable fields */}
              {[
                ["beneficiary_email", "Email"],
                ["beneficiary_mobile", "Mobile"],
                ["beneficiary_add", "Address"],
                ["beneficiary_city", "City"],
                ["beneficiary_state", "State"],
                ["beneficiary_pin_code", "PIN Code"],
              ].map(([key, label]) => (
                <Grid item xs={12} md={4} key={key}>
                  <TextField
                    fullWidth
                    className="mui-autofill-fix"
                    label={label}
                    value={form[key]}
                    disabled={loading}
                    inputProps={
                      key === "beneficiary_mobile"
                        ? { maxLength: 10, inputMode: "numeric" }
                        : undefined
                    }
                    onChange={(e) => {
                      if (key === "beneficiary_mobile") {
                        const onlyDigits = e.target.value.replace(/\D/g, "");
                        if (onlyDigits.length <= 10) setField(key, onlyDigits);
                      } else {
                        setField(key, e.target.value);
                      }
                    }}
                  />
                </Grid>
              ))}
            </>
          )}


        </Grid>

        {verified && (
          <Box mt={3} textAlign="center">
            <Button
              variant="contained"
              disabled={loading}
              onClick={() => {
                const amt = Number(form.transfer_amount);
                if (!amt || amt <= 0) {
                  toastMessage(true, "Enter valid transfer amount");
                  return;
                }
                if (isCashback) {
                  if (upiMin > 0 && amt < upiMin) {
                    toastMessage(true, `Minimum payout amount is ₹${upiMin.toLocaleString("en-IN")}`);
                    return;
                  }
                  if (upiMax > 0 && amt > upiMax) {
                    toastMessage(true, `Maximum payout limit per transaction is ₹${upiMax.toLocaleString("en-IN")}`);
                    return;
                  }
                }
                setOpenTpin(true);
              }}
            >
              Submit
            </Button>
          </Box>
        )}
      </Box>

      <Dialog open={openQr} maxWidth="xs" fullWidth>
        <DialogTitle align="center">Scan UPI QR</DialogTitle>
        <DialogContent>
          <Scanner
            constraints={{ facingMode: "environment" }}
            onScan={(r) => {
              const raw =
                typeof r === "string"
                  ? r
                  : r?.rawValue || r?.[0]?.rawValue;
              if (raw) handleQrData(raw);
            }}
          />
          <Box mt={2} textAlign="center">
            <Button component="label" variant="outlined" disabled={loading}>
              Upload QR
              <input
                hidden
                type="file"
                accept="image/*"
                onChange={(e) => {
                  const f = e.target.files?.[0];
                  if (!f) return;
                  const img = new Image();
                  img.src = URL.createObjectURL(f);
                  img.onload = () => {
                    const c = document.createElement("canvas");
                    const x = c.getContext("2d");
                    c.width = img.width;
                    c.height = img.height;
                    x.drawImage(img, 0, 0);
                    const d = x.getImageData(0, 0, c.width, c.height);
                    const code = jsQR(d.data, d.width, d.height);
                    if (code?.data) handleQrData(code.data);
                  };
                }}
              />
            </Button>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenQr(false)} disabled={loading}>
            Close
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={openTpin}>
        <DialogTitle align="center">Enter TPIN</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            className="mui-autofill-fix"
            type="password"
            value={tpin}
            inputProps={{ maxLength: 4 }}
            disabled={loading}
            onChange={(e) =>
              /^\d{0,4}$/.test(e.target.value) && setTpin(e.target.value)
            }
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenTpin(false)} disabled={loading}>
            Cancel
          </Button>
          <Button onClick={submitPayout} disabled={loading}>
            {loading ? "Processing..." : "Confirm"}
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default UpiTransferPage;
